script:
/* Shared styles for the Builder pages.

   Static styles (sizes, colors, spacing, layout) are NOT here: they are set on
   the blocks by generate.py, because Builder's editor canvas shows only block
   styles. This file holds what a block cannot express:
     - design tokens
     - hover, focus and active states
     - the mobile layout (Builder's breakpoints are 576 and 1024px, ours is 768px)
     - the elements that JavaScript creates (result rows, dialog)
   Values were measured from the Vue app's real frappe-ui components.
   The mobile rules use !important so they win over the block styles. */

/* InterVar comes from Builder's own reset.css, which every Builder page loads.
   Newsreader is registered as a Builder User Font (see generate.py). */

:root {
  --mna-surface: #ffffff;
  --mna-surface-2: #f3f3f3;
  --mna-surface-dark: #171717;
  --mna-hover: #ededed;
  --mna-outline: #ededed;
  --mna-ink: #0f0f0f;
  --mna-ink-8: #171717;
  --mna-ink-5: #7c7c7c;
  --mna-outline-strong: #999999;
}

html,
body {
  margin: 0;
  background: var(--mna-surface);
}

.mna-app {
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.mna-app *,
.mna-app *::before,
.mna-app *::after {
  box-sizing: border-box;
}
/* :where() keeps these resets at the lowest specificity, so a block's own
   color can still win. */
:where(.mna-app) a {
  color: inherit;
  text-decoration: none;
}
:where(.mna-app) button {
  font: inherit;
  letter-spacing: inherit;
  color: inherit;
}
/* Builder wraps every inline icon in a div. Without this the svg sits on the
   text baseline and the icon is a few pixels off-centre. */
.mna-app svg {
  display: block;
}

/* ---- Rail ---- */
.mna-rail-item:hover {
  background: rgba(0, 0, 0, 0.05);
}
.mna-rail-item.active {
  background: #fff;
  box-shadow:
    rgba(255, 255, 255, 0.16) 0 0.25px 1.5px 0 inset,
    rgba(0, 0, 0, 0.2) 0 0 1px 0,
    rgba(0, 0, 0, 0.14) 0 1px 3px 0;
}
/* The shell's HTML carries inline styles (so the editor canvas shows it), and
   inline styles beat class rules. The states that JavaScript toggles, and the
   ones that change what the inline styles set, therefore use !important. */
.mna-badge.show {
  display: block !important;
}

/* ---- Logo menu ---- */
.mna-menu.open {
  display: block !important;
}
.mna-menu-item:hover {
  background: var(--mna-surface-2) !important;
}

/* ---- Confirm dialog (Logout). Created by shell.js. ---- */
.mna-overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(0, 0, 0, 0.27);
}
/* Dialogs and toasts are added to <body>, outside .mna-app, so they set the
   base text style themselves. */
.mna-overlay,
.mna-toast {
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  line-height: 1.15;
  letter-spacing: 0.02em;
  color: var(--mna-ink);
  -webkit-font-smoothing: antialiased;
}
.mna-overlay *,
.mna-overlay *::before,
.mna-overlay *::after {
  box-sizing: border-box;
}
.mna-dialog {
  position: relative;
  width: 100%;
  max-width: 400px;
  padding: 22px 24px 28px;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.2);
}
.mna-dialog h2 {
  margin: 0;
  padding-right: 40px;
  font-size: 18px;
  font-weight: 600;
  line-height: 24px;
  color: var(--mna-ink);
}
.mna-dialog-close {
  position: absolute;
  top: 20px;
  right: 24px;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--mna-ink-8);
  cursor: pointer;
}
.mna-dialog-close:hover {
  background: var(--mna-surface-2);
}
.mna-dialog-close svg {
  width: 16px;
  height: 16px;
}
.mna-dialog p {
  margin: 12px 0 0;
  color: var(--mna-ink-5);
  font-size: 14px;
}
.mna-dialog:focus {
  outline: none;
}
.mna-dialog.wide {
  max-width: 448px;
}
.mna-dialog-actions {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: 40px;
}
.mna-dialog-left,
.mna-dialog-right {
  display: flex;
  gap: 8px;
}
.mna-dialog-right {
  margin-left: auto;
}
.mna-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 28px;
  padding: 0 8px;
  border: 0;
  border-radius: 8px;
  font-size: 14px;
  white-space: nowrap;
  cursor: pointer;
}
.mna-btn-solid {
  background: var(--mna-surface-dark);
  color: #fff;
}
.mna-btn-solid:hover {
  background: #383838 !important;
}
.mna-btn-subtle {
  background: var(--mna-surface-2);
  color: var(--mna-ink-8);
}
.mna-btn-subtle:hover {
  background: var(--mna-hover);
}
.mna-btn-outline {
  border: 1px solid #e2e2e2;
  background: #fff;
  color: var(--mna-ink-8);
}
.mna-btn-outline:hover {
  background: #f8f8f8;
}
.mna-btn-danger {
  background: #e03636;
  color: #fff;
}
.mna-btn-danger:hover {
  background: #c62f2f;
}
.mna-btn-danger-ghost {
  background: transparent;
  color: #e03636;
}
.mna-btn-danger-ghost:hover {
  background: #fdeeee;
}
.mna-btn:disabled {
  opacity: 0.6;
  cursor: default;
}

/* ---- Form dialogs. Created by ui.js. ---- */
.mna-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 26px;
}
.mna-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.mna-field.grow {
  flex: 1;
}
.mna-field label {
  font-size: 14px;
  line-height: 1.15;
  color: var(--mna-ink-5);
}
.mna-field input,
.mna-field select,
.mna-field textarea {
  display: block;
  width: 100%;
  height: 28px;
  padding: 6px 8px;
  border: 1px solid var(--mna-surface-2);
  border-radius: 8px;
  outline: none;
  background: var(--mna-surface-2);
  color: var(--mna-ink-8);
  font: inherit;
  font-size: 14px;
  line-height: 1.15;
  letter-spacing: 0.02em;
}
.mna-field textarea {
  height: auto;
  resize: vertical;
}
.mna-field input:hover,
.mna-field select:hover,
.mna-field textarea:hover {
  background: var(--mna-hover);
  border-color: var(--mna-hover);
}
.mna-field input:focus,
.mna-field select:focus,
.mna-field textarea:focus {
  background: #fff;
  border-color: var(--mna-outline-strong);
}
.mna-field .invalid {
  border-color: #e03636;
}
.mna-field-row {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.mna-field-text {
  padding-bottom: 6px;
  font-size: 16px;
  line-height: 24px;
  color: var(--mna-ink-5);
}
.mna-required {
  color: #e03636;
}
.mna-form-error {
  margin: 12px 0 0;
  color: #e03636;
  font-size: 13px;
}
.mna-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  z-index: 70;
  padding: 8px 12px;
  border-radius: 8px;
  background: var(--mna-surface-dark);
  color: #fff;
  transform: translateX(-50%);
  transition: opacity 0.3s;
}
.mna-toast.leaving {
  opacity: 0;
}

/* ---- Header ---- */
.mna-crumbs a:hover {
  color: var(--mna-ink);
}

/* ---- Search page ---- */
.mna-search input {
  font-family: inherit;
}
.mna-search input::placeholder {
  color: var(--mna-outline-strong);
}
.mna-search input:hover {
  background: var(--mna-hover) !important;
  border-color: var(--mna-hover) !important;
}
.mna-search input:focus {
  background: #fff !important;
  border-color: var(--mna-outline-strong) !important;
  box-shadow:
    rgba(255, 255, 255, 0.16) 0 0.25px 1.5px 0 inset,
    rgba(0, 0, 0, 0.2) 0 0 1px 0,
    rgba(0, 0, 0, 0.14) 0 1px 3px 0;
}

/* Result rows. Created by search.js. */
.mna-person {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 44px;
  padding: 6px 8px;
  border-radius: 8px;
}
.mna-person:hover {
  background: #fafafa;
}
.mna-avatar {
  display: grid;
  place-items: center;
  flex: none;
  width: 32px;
  height: 32px;
  overflow: hidden;
  border-radius: 9999px;
  background: var(--mna-surface-2);
  color: var(--mna-ink-5);
  font-size: 16px;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.mna-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.mna-person-name {
  overflow: hidden;
  font-size: 16px;
  letter-spacing: 0.02em;
  color: #000;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mna-empty {
  padding: 40px 0;
  text-align: center;
  font-size: 16px;
  letter-spacing: 0.02em;
  color: #6b6b6b;
}

/* ---- Profile page ---- */
.mna-outline-btn:hover {
  background: #f8f8f8 !important;
}
.mna-icon-btn:hover {
  background: rgba(0, 0, 0, 0.06) !important;
}
.mna-text-btn:hover {
  background: var(--mna-surface-2) !important;
}
.mna-text-btn[data-action='toggle-bio']:hover {
  background: transparent !important;
  color: var(--mna-ink-8);
  text-decoration: underline;
}
.mna-clamp-2,
.mna-clamp-3 {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.mna-clamp-2 {
  -webkit-line-clamp: 2;
}
.mna-clamp-3 {
  -webkit-line-clamp: 3;
}
.mna-clamp-3.expanded {
  display: block;
}
/* Rows of a list are separated by a line; the first and last touch the card edge. */
.mna-posts > * + *,
.mna-entries > * + * {
  border-top: 1px solid var(--mna-outline);
}
.mna-posts > :first-child,
.mna-entries > :first-child {
  padding-top: 0;
}
.mna-posts > :last-child,
.mna-entries > :last-child {
  padding-bottom: 0;
}
/* Work and education show three items until "Show all" is clicked. */
.mna-entries:not(.expanded) > :nth-child(n + 4) {
  display: none;
}
.mna-entries:not(.expanded) > :nth-child(3) {
  padding-bottom: 0;
}
.mna-profile-initial {
  font-size: 40px;
  font-weight: 500;
  line-height: 1.5;
  color: var(--mna-ink-5);
  text-transform: uppercase;
}

/* ---- Mobile: rail becomes a bottom bar ---- */
@media (max-width: 767px) {
  .mna-rail,
  .mna-header,
  .mna-menu {
    display: none !important;
  }
  .mna-app {
    flex-direction: column !important;
  }
  .mna-container {
    padding: 24px 16px !important;
  }
  .mna-scroll {
    padding-bottom: 57px;
  }
  .mna-bottom-nav {
    position: fixed;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 40;
    display: flex !important;
    height: 57px;
    border-top: 1px solid #e2e2e2;
    background: #fff;
  }
  .mna-tab {
    position: relative;
    display: flex;
    flex: 1;
    align-items: center;
    justify-content: center;
    padding: 8px 0;
    color: var(--mna-ink-5);
  }
  .mna-tab.active {
    color: var(--mna-ink);
  }
  .mna-tab .mna-badge {
    top: 8px !important;
    right: calc(50% - 20px) !important;
  }
  .mna-profile-head {
    gap: 16px !important;
  }
  .mna-profile-avatar {
    width: 80px !important;
    height: 80px !important;
  }
  .mna-profile-avatar .mna-profile-initial {
    font-size: 32px !important;
    line-height: 1.5 !important;
  }
  .mna-name-row {
    flex-direction: column !important;
    align-items: flex-start !important;
  }
  .mna-profile-name {
    max-width: 100%;
    font-size: 20px !important;
    line-height: 1.15 !important;
    letter-spacing: 0.01em !important;
  }
}
